use air_core::store::{Store,parse_tsv,Fact};
use std::{fs::{File,OpenOptions},io::{self,Read,BufRead,BufReader,BufWriter,Write},path::Path};
fn show(f:&Fact){println!("{} | {} | {} | sources: {:?}",f.subject,f.relation,f.object,f.sources);}
fn run()->Result<(),Box<dyn std::error::Error>>{
 let a:Vec<String>=std::env::args().collect();match a.get(1).map(String::as_str){
 Some("index-import") if a.len()==4=>{use air_core::{indexed::{Indexed,Limits},curate::curate};let path=Path::new(&a[3]);let _file=OpenOptions::new().write(true).create_new(true).open(path)?;let result=(||->Result<u64,Box<dyn std::error::Error>>{let mut db=Indexed::create(path,Limits::default())?;let mut r=BufReader::new(File::open(&a[2])?);let mut line=String::new();loop{line.clear();let n=std::io::Read::take(&mut r,262145).read_line(&mut line)?;if n==0{break}if n>262144{return Err("line too large".into())}let l=line.trim_end_matches(['\r','\n']);if !l.is_empty()&&!l.starts_with('#'){db.insert(&curate(l)?)?;}}db.len()})();match result{Ok(n)=>println!("Indexed {n} unique unverified claims"),Err(e)=>{let _=std::fs::remove_file(path);return Err(e)}}},
 Some("ask") if a.len()==4||a.len()==5=>{use air_core::{indexed::{Indexed,Limits},router::{choose,execute,parse_model_route,Answer,Route}};let db=Indexed::open(Path::new(&a[2]),Limits::default())?;let model=match std::env::var("AIR_MODEL_PORT"){Ok(p)=>Some(air_core::model::LocalModel::new(p.parse()?,&std::env::var("AIR_MODEL_NAME").unwrap_or_else(|_|"local".into()))?),Err(_)=>None};let mut route=choose(&a[3],model.as_ref().map(|m|m as &dyn air_core::router::SemanticRouter))?;if route==Route::Unknown&&a.len()==5{route=parse_model_route(&a[4])?;}match execute(&db,&a[3],route)?{Answer::Claims(r)=>{if r.facts.is_empty(){println!("No matching claim");}else{println!("Unverified stored claims:");for f in &r.facts{show(f);}}if r.truncated{println!("Results truncated by retrieval budget");}},Answer::Number(n)=>println!("{n}"),Answer::Paths(p)=>{println!("Unverified evidence paths:");for x in &p.paths{show(&x.first);show(&x.second);}if p.truncated{println!("Paths truncated");}},Answer::Unknown{suggested_categories}=>println!("Unsupported question; suggested categories: {suggested_categories:?}")}},
 Some("curate-text") if a.len()==5=>{use air_core::{indexed::{Indexed,Limits},model::LocalModel};let model=LocalModel::new(std::env::var("AIR_MODEL_PORT")?.parse()?,&std::env::var("AIR_MODEL_NAME").unwrap_or_else(|_|"local".into()))?;let mut text=String::new();std::io::Read::take(File::open(&a[2])?,16385).read_to_string(&mut text)?;let claims=model.extract(&text,&a[4])?;let path=Path::new(&a[3]);let _f=OpenOptions::new().write(true).create_new(true).open(path)?;let result=(||->Result<(),Box<dyn std::error::Error>>{let mut db=Indexed::create(path,Limits::default())?;for f in &claims{db.insert(f)?;}Ok(())})();if let Err(e)=result{let _=std::fs::remove_file(path);return Err(e)}println!("{} extracted claims, unverified",claims.len());},
 Some("doctor") if a.len()==2=>println!("AIR structured knowledge prototype; arch={} os={}; optional local model server supported",std::env::consts::ARCH,std::env::consts::OS),
 Some("import") if a.len()==4=>{let mut s=Store::default();let mut r=BufReader::new(File::open(&a[2])?);let mut line=String::new();let mut n=0;loop{line.clear();let read=std::io::Read::take(&mut r,262145).read_line(&mut line)?;if read==0{break;}if read>262144{return Err("line too large".into());}n+=1;let l=line.trim_end_matches(['\r','\n']);if l.is_empty()||l.starts_with('#'){continue;}s.insert(parse_tsv(l).map_err(|e|format!("line {n}: {e}"))?)?;}
 let path=Path::new(&a[3]);let mut w=BufWriter::new(OpenOptions::new().write(true).create_new(true).open(path)?);if let Err(e)=s.write(&mut w).and_then(|_|w.flush()){drop(w);let _=std::fs::remove_file(path);return Err(e.into());}println!("Imported {} unique records; source claims are not verified",s.len());}
 Some("lookup") if a.len()==5=>{let s=Store::read(BufReader::new(File::open(&a[2])?))?;let f=s.lookup(&a[3],&a[4],100);if f.is_empty(){println!("No matching claim");}else{if f.len()>1{println!("Multiple claims; not resolved");}for x in f{show(x);}}}
 Some("category") if a.len()==4=>{let s=Store::read(BufReader::new(File::open(&a[2])?))?;for f in s.category(&a[3],100){show(f);}}
 _=>return Err(io::Error::new(io::ErrorKind::InvalidInput,"Usage: air-cli doctor | import INPUT.tsv NEW.air | lookup STORE SUBJECT RELATION | category STORE CATEGORY | index-import INPUT.tsv NEW.db | ask DB QUESTION [ROUTE_JSON] | curate-text INPUT NEW.db SOURCE").into())
 }Ok(())
}
fn main(){if let Err(e)=run(){eprintln!("{e}");std::process::exit(2);}}
